import React, { useState } from 'react';

const demoAccounts = {
  owner: { email: 'owner@crm-demo.in', password: 'Owner@123', name: 'CRM Owner', role: 'owner' },
  employee: { email: 'employee@crm-demo.in', password: 'Employee@123', name: 'Sales Employee', role: 'employee' },
};

export default function Login({ onLogin }) {
  const [role, setRole] = useState('owner');
  const [email, setEmail] = useState(demoAccounts.owner.email);
  const [password, setPassword] = useState(demoAccounts.owner.password);
  const [error, setError] = useState('');
  const chooseRole = (next) => {
    setRole(next);
    setEmail(demoAccounts[next].email);
    setPassword(demoAccounts[next].password);
    setError('');
  };
  function submit(e) {
    e.preventDefault();
    const account = demoAccounts[role];
    if (email.trim().toLowerCase() === account.email && password === account.password) {
      onLogin({ name: account.name, email: account.email, role: account.role });
    } else {
      setError('Login details match nahi hue. Demo credentials check karein.');
    }
  }
  return <main className="login-screen">
    <section className="login-art">
      <div className="login-brand"><span className="brand-mark">R<span>+</span></span><div><b>RealEstate<span>Pro</span></b><small>CRM WORKSPACE</small></div></div>
      <div className="login-copy"><span className="eyebrow">ONE WORKSPACE. EVERY OPPORTUNITY.</span><h1>Build better<br/>customer relationships.</h1><p>Leads, follow-ups, site visits, bookings and team activity — all in one organized workspace.</p>
        <div className="login-feature"><span>✓</span> Lead pipeline & team assignment</div><div className="login-feature"><span>✓</span> Owner and employee workspaces</div><div className="login-feature"><span>✓</span> Designed for desktop and mobile</div>
      </div>
      <div className="login-art-footer">CRM UI prototype · Connect a production database before real use</div>
    </section>
    <section className="login-side"><form className="login-card" onSubmit={submit}>
      <div className="mobile-login-brand"><span className="brand-mark">R<span>+</span></span><b>RealEstate<span>Pro</span></b></div>
      <span className="eyebrow">WELCOME BACK</span><h2>Sign in to your workspace</h2><p className="login-subtitle">Choose your account type to continue.</p>
      <div className="role-switch"><button type="button" className={role==='owner'?'selected':''} onClick={()=>chooseRole('owner')}><span>♛</span> Owner</button><button type="button" className={role==='employee'?'selected':''} onClick={()=>chooseRole('employee')}><span>♙</span> Employee</button></div>
      <label className="login-label">Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username" required/></label>
      <label className="login-label">Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></label>
      {error&&<div className="login-error" role="alert">{error}</div>}
      <button className="login-submit" type="submit">Sign in <span>→</span></button>
      <div className="demo-credentials"><b>Demo login details</b><span>{demoAccounts[role].email}</span><span>{demoAccounts[role].password}</span><small>Demo only — not secure authentication. Replace with Firebase Auth / server authentication before launch.</small></div>
    </form></section>
  </main>;
}
